import json
with open('memory.json', 'r') as f:
    data = json.load(f)
# Search for heterocycle formation examples
for item in data:
    if isinstance(item, dict):
        context = item.get('Context', '')
        if 'Heterocycle' in context or 'heterocycle' in context.lower():
            print(json.dumps(item, indent=2))
            print('---')
""}

{"command": "cd /harness/memory && python3 -c "
import json
with open('memory.json', 'r') as f:
    data = json.load(f)
print(type(data))
if isinstance(data, list):
    print(f'Number of items: {len(data)}')
    for i, item in enumerate(data[:5]):
        print(f'Item {i}: {type(item)}')
        if isinstance(item, dict):
            print(item.keys() if hasattr(item, 'keys') else 'no keys')
""}

